package com.example.flashcardapp.viewmodel

import android.content.Context
import androidx.lifecycle.LiveData
import androidx.lifecycle.MutableLiveData
import androidx.lifecycle.ViewModel
import com.example.flashcardapp.data.Flashcard
import com.example.flashcardapp.data.FlashcardRepository
import com.example.flashcardapp.data.Topic
import com.example.flashcardapp.main.ChatGPTHelper
import com.example.flashcardapp.util.FlashcardUtils
import kotlinx.coroutines.CoroutineScope
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.launch
import kotlinx.coroutines.withContext

class ImportFlashcardsViewModel : ViewModel() {

    private val topicCache: MutableMap<String, Topic> = HashMap()

    // Updated so we can store newly generated questions here.
    private val generatedQuestions = MutableLiveData<List<Flashcard>>(arrayListOf())
    fun getGeneratedQuestions(): LiveData<List<Flashcard>> {
        return generatedQuestions
    }

    private lateinit var repository: FlashcardRepository

    fun initialize(repository: FlashcardRepository) {
        this.repository = repository
        preloadTopicCache()
    }

    private fun preloadTopicCache() {
        // We'll do this in a coroutine.
        CoroutineScope(Dispatchers.IO).launch {
            val existingTopics = repository.getAllTopics()
            for (t in existingTopics) {
                topicCache[t.name] = t
            }
        }
    }

    fun fetchExistingQuestions(callback: OnLoadCallback) {
        // Example approach: do it in a coroutine, then callback
        CoroutineScope(Dispatchers.IO).launch {
            val list = repository.getAllFlashcards()
            withContext(Dispatchers.Main) {
                callback.onLoaded(list)
            }
        }
    }

    fun saveFlashcards(flashcards: List<Flashcard>) {
        CoroutineScope(Dispatchers.IO).launch {
            for (f in flashcards) {
                // We check if question/answer are not empty.
                if (f.question.isNotEmpty() && f.answer.isNotEmpty()) {
                    repository.insertFlashcard(f)
                    // If you want to handle topics, do so here.
                }
            }
        }
    }

    // We fill out this method to call ChatGPTHelper, parse the returned JSON array,
    // then post the results to our LiveData.
    fun generateQuestions(
        existingQuestions: List<Flashcard>,
        prompt: String,
        context: Context,
        callback: OnGenerateCallback
    ) {
        // Optional: incorporate existingQuestions into the prompt if desired
        // For now, we just use prompt as-is.
        ChatGPTHelper.generateMultipleQuestions(prompt, context, object : ChatGPTHelper.OnChatGPTResponse {
            override fun onSuccess(response: String) {
                try {
                    // 'response' should be a JSON array (per generateMultipleQuestions doc).
                    val newFlashcards = FlashcardUtils.parseFlashcardsFromJson(response)

                    // Post the new flashcards to generatedQuestions so the UI sees them.
                    generatedQuestions.postValue(newFlashcards)

                    // Indicate success in the callback
                    callback.onSuccess()
                } catch (e: Exception) {
                    callback.onFailure("Error parsing generated questions: ${'$'}{e.message}")
                }
            }

            override fun onFailure(error: String) {
                callback.onFailure(error)
            }
        })
    }

    interface OnGenerateCallback {
        fun onSuccess()
        fun onFailure(error: String)
    }

    interface OnLoadCallback {
        fun onLoaded(list: List<Flashcard>)
    }

    override fun onCleared() {
        super.onCleared()
        // no need to close repository
    }
}
